<?php

declare(strict_types=1);
namespace Moves\Controllers;
use Moves\Core\Controller;use Moves\Core\Auth;use Moves\Core\Csrf;use Moves\Core\Request;use Moves\Core\Response;use MovesCode\Router\Router;use Moves\Services\Talk\TalkService;use Moves\Services\Talk\TalkMetadataService;use Moves\Services\Talk\TalkNotificationService;use Moves\Services\Talk\TalkAttachmentService;use Moves\Services\Talk\TalkOutboundService;use Moves\Services\Talk\TalkChannelService;
final class TalkController extends Controller
{
private TalkService $talk;private TalkMetadataService $metadata;private TalkNotificationService $notifications;private TalkAttachmentService $attachments;private TalkOutboundService $outbound;private TalkChannelService $channelService;
public function __construct(Router $router){parent::__construct($router);$this->talk=new TalkService();$this->metadata=new TalkMetadataService();$this->notifications=new TalkNotificationService();$this->attachments=new TalkAttachmentService();$this->outbound=new TalkOutboundService();$this->channelService=new TalkChannelService();}
public function dashboard(array $route=[]):void{
$user=Auth::user();if($user===null){Response::to('/login');}
$this->talk->heartbeat((int)$user->id);
$legacyView=(string)($_GET['view']??'');if($legacyView!==''&&empty($route['view'])){Response::to('/talk/view/'.rawurlencode($legacyView));}$view=(string)($route['view']??'inbox');$allowed=['inbox','queue','contacts','history','connection','jack','team','settings'];if(!in_array($view,$allowed,true))$view='inbox';
$conversations=$this->talk->conversations((string)($_GET['q']??''));$visible=[];$scope=(string)($_GET['scope']??'all');foreach($conversations as $conversation){$ticketId=(int)($conversation['ticket_id']??0);if($ticketId<=0||!$this->talk->canViewTicket($ticketId,(int)$user->id))continue;$status=(string)($conversation['ticket_status']??$conversation['status']??'');if($scope==='attending'&&!in_array($status,['assigned','open'],true))continue;if($scope==='unread'&&(int)($conversation['unread_count']??0)<=0)continue;$visible[]=$conversation;}
$selected = null;
$selectedId = max(0, (int) ($_GET['ticket'] ?? 0));
if ($view === 'inbox' && $selectedId > 0 && $this->talk->canViewTicket($selectedId, (int) $user->id)) {
    $this->talk->markTicketRead($selectedId);
    foreach ($visible as &$conversation) {
        if ((int) ($conversation['ticket_id'] ?? 0) === $selectedId) {
            $conversation['unread_count'] = 0;
        }
    }
    unset($conversation);
    $selected = $this->talk->ticket($selectedId);
    if ($selected !== null) {
        $selected['tags'] = $this->metadata->ticketTags($selectedId);
        $selected['available_tags'] = $this->metadata->tags();
        $selected['attachments'] = $this->attachments->forTicket($selectedId);
    }
}
$data=['title'=>'Talk','productName'=>'Talk','activeProduct'=>'talk','currentPage'=>'dashboard','talkView'=>$view,'conversations'=>$visible,'selectedTicket'=>$selected];
if($view==='queue'){$data['queue']=$this->metadata->search(['q'=>'','status'=>'queued','priority'=>'','queue_id'=>0,'tag_id'=>0]);}
elseif($view==='contacts'){$data['contacts']=$this->talk->contacts();}
elseif($view==='history'){$data['tickets']=$this->metadata->search(['q'=>'','status'=>'closed','priority'=>'','queue_id'=>0,'tag_id'=>0]);}
elseif($view==='connection'){$data['channels']=$this->channelService->channels();$data['channelQueues']=$this->channelService->queues();}
elseif($view==='jack'){$data['jack_interactions']=$this->talk->jackInteractions();}
elseif($view==='team'){$data['users']=$this->talk->usersWithPresence();}
elseif($view==='settings'){$data['settings']=$this->talk->settings();}
echo $this->view->render('pages/talk-inbox',$data);
}
public function whatsappStatus(array $route=[]):never{$user=Auth::user();if($user===null){$this->json(['error'=>'unauthorized'],401);}$id=max(0,(int)($route['id']??0));try{$this->json($this->channelService->status($id));}catch(\Throwable $e){$this->json(['error'=>$e->getMessage()],404);}}
public function channelSave():void{$this->requireCsrf('/talk/view/connection');$user=Auth::user();try{$id=$this->channelService->save($_POST,(int)$user->id);Response::to('/talk/view/connection?saved='.$id);}catch(\Throwable $e){Response::to('/talk/view/connection?error='.rawurlencode($e->getMessage()));}}
public function channelConnect(array $route=[]):never{$this->channelAction($route,'connect');}
public function channelDisconnect(array $route=[]):never{$this->channelAction($route,'disconnect');}
public function channelRemove(array $route=[]):never{$this->channelAction($route,'remove');}
public function channelLogout(array $route=[]):never{$this->channelAction($route,'logout');}
private function channelAction(array $route,string $action):never{$user=Auth::user();if($user===null)$this->json(['error'=>'unauthorized'],401);try{$this->requireCsrf('/talk/view/connection');$id=max(0,(int)($route['id']??0));$result=match($action){'connect'=>$this->channelService->connect($id,(int)$user->id),'disconnect'=>$this->channelService->disconnect($id,(int)$user->id),'remove'=>$this->channelService->remove($id,(int)$user->id),default=>$this->channelService->logout($id,(int)$user->id)};$this->json($result);}catch(\Throwable $e){$this->json(['error'=>$e->getMessage()],422);}}
/** @param array<string,mixed> $payload */private function json(array $payload,int $status=200):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');echo json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
public function queue():void{if(Request::isMethod('POST')){$this->requireCsrf('/talk/queue');$user=Auth::user();$ticketId=max(0,(int)Request::post('ticket_id',0));if($user===null||$ticketId===0){Response::to('/talk/queue?error=invalid');}$claimed=$this->talk->claim($ticketId,(int)$user->id);Response::to('/talk/view/inbox?ticket='.$ticketId.'&'.($claimed?'claimed=1':'error=unavailable'));}$filters=$this->filters();$filters['status']='queued';$this->page('Fila','queue','Atendimentos aguardando um atendente elegível.',['queue'=>$this->metadata->search($filters),'filters'=>$filters,'queues'=>$this->talk->queues(),'tags'=>$this->metadata->tags()]);}
public function simulate():never{$this->requireCsrf('/talk/queue');$user=Auth::user();if($user===null){Response::to('/login');}Response::to('/talk/view/inbox?ticket='.$this->talk->seedSimulation((int)$user->id));}
/** @param array<string,string> $data */public function ticket(array $data=[]):void{$id=max(0,(int)($data['id']??0));$ticket=$this->talk->ticket($id);if($ticket===null){Response::to('/talk/queue');}$viewer=Auth::user();if($viewer===null||!$this->talk->canViewTicket($id,(int)$viewer->id)){Response::to('/talk/my-tickets?error=forbidden');}if(Request::isMethod('POST')){$this->requireCsrf('/talk/tickets/'.$id);$user=Auth::user();if($user===null){Response::to('/login');}$action=(string)Request::post('action','');$userId=(int)$user->id;if($action==='send'){try{$this->outbound->sendText($id,$userId,(string)Request::post('body',''),(string)Request::post('idempotency_key',''));$_SESSION['talk_outbound_status']='pending';}catch(\Throwable $e){$_SESSION['talk_outbound_error']=$e instanceof \RuntimeException?$e->getMessage():'Não foi possível registrar a mensagem.';}}elseif($action==='attachment'){try{$this->attachments->store($id,$userId,$_FILES['attachment']??[]);}catch(\RuntimeException $e){$_SESSION['talk_attachment_error']=$e->getMessage();}}elseif($action==='note'){$this->talk->addNote($id,$userId,mb_substr(trim((string)Request::post('body','')),0,4000));}elseif($action==='priority'){$this->metadata->updatePriority($id,$userId,(string)Request::post('priority','normal'));}elseif($action==='create_tag'){try{$this->metadata->createAndAttachTag($id,$userId,(string)Request::post('tag_name',''));}catch(\RuntimeException $e){$_SESSION['talk_tag_error']=$e->getMessage();Response::to('/talk/tickets/'.$id);}}elseif($action==='attach_tag'){$this->metadata->attachTag($id,max(1,(int)Request::post('tag_id',0)),$userId);}elseif($action==='detach_tag'){$this->metadata->detachTag($id,max(1,(int)Request::post('tag_id',0)),$userId);}elseif($action==='return_queue'){$this->talk->returnToQueue($id,$userId);Response::to('/talk/view/queue');}elseif($action==='close'){$this->talk->close($id,$userId);Response::to('/talk/view/history');}elseif($action==='reopen'){$this->talk->reopen($id,$userId);Response::to('/talk?view=queue');}elseif($action==='transfer'){$toUser=max(0,(int)Request::post('to_user_id',0));$toQueue=max(0,(int)Request::post('to_queue_id',0));try{$this->talk->transfer($id,$userId,$toUser>0?$toUser:null,$toQueue>0?$toQueue:null,mb_substr(trim((string)Request::post('reason','')),0,500));}catch(\RuntimeException $e){$_SESSION['talk_transfer_error']=$e->getMessage();Response::to('/talk/tickets/'.$id);}}Response::to('/talk/view/inbox?ticket='.$id);}$ticket['tags']=$this->metadata->ticketTags($id);$ticket['available_tags']=$this->metadata->tags();$ticket['attachments']=$this->attachments->forTicket($id);$ticket['attachment_error']=$_SESSION['talk_attachment_error']??null;$ticket['outbound_error']=$_SESSION['talk_outbound_error']??null;$ticket['outbound_status']=$_SESSION['talk_outbound_status']??null;$ticket['transfer_error']=$_SESSION['talk_transfer_error']??null;$ticket['tag_error']=$_SESSION['talk_tag_error']??null;unset($_SESSION['talk_attachment_error'],$_SESSION['talk_outbound_error'],$_SESSION['talk_outbound_status'],$_SESSION['talk_transfer_error'],$_SESSION['talk_tag_error']);echo $this->view->render('pages/talk-ticket',['title'=>'Atendimento '.(string)$ticket['protocol'],'productName'=>'Talk','activeProduct'=>'talk','currentPage'=>'my-tickets','ticket'=>$ticket]);}
/** @param array<string,string> $data */public function attachment(array $data=[]):never{$id=max(0,(int)($data['id']??0));$user=Auth::user();$attachment=$id>0?$this->attachments->find($id):null;if($user===null||$attachment===null||!$this->talk->canViewTicket((int)$attachment['ticket_id'],(int)$user->id)){http_response_code(404);exit;}$root=realpath(dirname(__DIR__,2));$path=$root!==false?realpath($root.'/'.ltrim((string)$attachment['storage_path'],'/')):false;$storageRoot=$root!==false?realpath($root.'/storage/talk'):false;if($path===false||$storageRoot===false||!str_starts_with($path,$storageRoot.DIRECTORY_SEPARATOR)||!is_file($path)){http_response_code(404);exit;}$mime=(string)$attachment['mime_type'];$inline=str_starts_with($mime,'image/')||str_starts_with($mime,'audio/')||str_starts_with($mime,'video/')||$mime==='application/pdf';$name=preg_replace('/[^\pL\pN._()\- ]/u','_',(string)$attachment['original_name'])?:'arquivo';header_remove('X-Powered-By');header('X-Content-Type-Options: nosniff');header('Cache-Control: private, max-age=300');header('Content-Type: '.$mime);header('Content-Length: '.(string)filesize($path));header('Content-Disposition: '.($inline?'inline':'attachment').'; filename="'.str_replace(['"','\\'],'_',$name).'"');readfile($path);exit;}
public function sync():never{
    $user=Auth::user();if($user===null){$this->json(['error'=>'unauthorized'],401);}
    $userId=(int)$user->id;
    $this->talk->heartbeat($userId);
    $state=$this->talk->syncState($userId);
    $state['notifications']=$this->notifications->unreadCount($userId);
    if(($_GET['include']??'')==='snapshot'){
        $rows=$this->talk->conversations(mb_substr(trim((string)($_GET['q']??'')),0,100));
        $state['conversations']=array_values(array_filter($rows,fn(array $row):bool=>(int)($row['ticket_id']??0)>0&&$this->talk->canViewTicket((int)$row['ticket_id'],$userId)));
        $ticketId=max(0,(int)($_GET['ticket']??0));
        $state['ticket']=$ticketId>0&&$this->talk->canViewTicket($ticketId,$userId)?$this->talk->ticket($ticketId):null;
    }
    $this->json($state);
}
public function conversations():void{$this->page('Conversas','conversations','Conversas ativas e seus respectivos atendimentos.',['conversations'=>$this->talk->conversations()]);}public function contacts():void{$this->page('Contatos','contacts','Pessoas identificadas a partir dos canais conectados.',['contacts'=>$this->talk->contacts()]);}public function myTickets():void{$user=Auth::user();if($user===null){Response::to('/login');}$filters=$this->filters();$this->page('Meus chamados','my-tickets','Atendimentos atualmente sob sua responsabilidade.',['tickets'=>$this->metadata->search($filters,(int)$user->id),'filters'=>$filters,'queues'=>$this->talk->queues(),'tags'=>$this->metadata->tags()]);}public function transfers():void{$this->page('Transferências','transfers','Transferências recebidas, enviadas e pendentes.',['transfers'=>$this->talk->transfers()]);}public function history():void{$filters=$this->filters();$filters['status']='closed';$this->page('Histórico','history','Atendimentos finalizados e histórico operacional.',['tickets'=>$this->metadata->search($filters),'filters'=>$filters,'queues'=>$this->talk->queues(),'tags'=>$this->metadata->tags()]);}
public function notifications():void{$user=Auth::user();if($user===null){Response::to('/login');}$userId=(int)$user->id;if(Request::isMethod('POST')){$this->requireCsrf('/talk/notifications');$action=(string)Request::post('action','');if($action==='read'){$this->notifications->markRead(max(1,(int)Request::post('notification_id',0)),$userId);}elseif($action==='read_all'){$this->notifications->markAllRead($userId);}Response::to('/talk/notifications');}echo $this->view->render('pages/talk-notifications',['title'=>'Notificações','productName'=>'Talk','activeProduct'=>'talk','currentPage'=>'notifications','notifications'=>$this->notifications->unread($userId,100),'notificationCount'=>$this->notifications->unreadCount($userId)]);}
public function jack():void{$this->page('Interações do Jack','jack','Revise atendimentos, respostas e decisões do agente virtual.',['jack_interactions'=>$this->talk->jackInteractions()]);}public function jackSettings():void{$user=Auth::user();if($user===null){Response::to('/login');}if(Request::isMethod('POST')){$this->requireCsrf('/talk/jack/settings');$this->talk->saveSettings(['jack.enabled'=>Request::post('jack_enabled')!==null?'1':'0','jack.wait_seconds'=>(string)max(0,(int)Request::post('jack_wait_seconds',60)),'jack.transfer_summary'=>Request::post('jack_transfer_summary')!==null?'1':'0'],(int)$user->id);Response::to('/talk/jack/settings?saved=1');}$this->page('Configuração do Jack','jack-settings','Defina quando e como o Jack participa do atendimento.',['settings'=>$this->talk->settings()]);}
public function queues():void{$user=Auth::user();if($user===null){Response::to('/login');}$manage=$this->talk->canManage((int)$user->id);if(Request::isMethod('POST')){$this->requireCsrf('/talk/queues');if(!$manage){Response::to('/talk/queues?error=forbidden');}$action=(string)Request::post('action','');if($action==='save_queue'){$this->talk->saveQueue(max(0,(int)Request::post('id',0)),mb_substr(trim((string)Request::post('name','')),0,120),($d=max(0,(int)Request::post('department_id',0)))>0?$d:null,max(5,(int)Request::post('auto_assign_after_seconds',30)),(string)Request::post('status','active'));}elseif($action==='save_department'){$this->talk->saveDepartment(max(0,(int)Request::post('id',0)),mb_substr(trim((string)Request::post('name','')),0,120),(string)Request::post('status','active'));}elseif($action==='save_member'){$this->talk->saveQueueMember(max(1,(int)Request::post('queue_id',0)),max(1,(int)Request::post('user_id',0)),(string)Request::post('role','agent'),max(1,(int)Request::post('capacity',5)),(string)Request::post('status','active'));}elseif($action==='remove_member'){$this->talk->removeQueueMember(max(1,(int)Request::post('queue_id',0)),max(1,(int)Request::post('user_id',0)));}Response::to('/talk/queues?saved=1');}$queues=$this->talk->queues();$members=[];foreach($queues as $q){$members[(int)$q['id']]=$this->talk->queueMembers((int)$q['id']);}$this->page('Filas e departamentos','queues','Organize departamentos, filas e capacidade de atendimento.',['queues'=>$queues,'departments'=>$this->talk->departments(),'members'=>$members,'users'=>$this->talk->eligibleUsers(),'canManage'=>$manage]);}
public function users():void{$user=Auth::user();if($user===null){Response::to('/login');}if(Request::isMethod('POST')){$this->requireCsrf('/talk/users');$action=(string)Request::post('action','presence');if($action==='presence'){$this->talk->updatePresence((int)$user->id,(string)Request::post('presence','online'));}elseif($action==='user_settings'){if(!$this->talk->canManage((int)$user->id)){Response::to('/talk/users?error=forbidden');}$this->talk->saveUserSettings(max(1,(int)Request::post('user_id',0)),(string)Request::post('talk_role','agent'),max(1,(int)Request::post('capacity',5)));}Response::to('/talk/users');}$users=$this->talk->usersWithPresence();$currentPresence='offline';foreach($users as $row){if((int)$row['id']===(int)$user->id){$currentPresence=(string)$row['presence'];break;}}$this->page('Usuários e permissões','users','Gerencie atendentes, supervisores e permissões do Talk.',['users'=>$users,'currentPresence'=>$currentPresence,'canManage'=>$this->talk->canManage((int)$user->id)]);}public function reports():void{$this->page('Relatórios','reports','Indicadores de fila, atendimento, transferência e SLA.',['reports'=>$this->talk->reports()]);}public function settings():void{$user=Auth::user();if($user===null){Response::to('/login');}if(Request::isMethod('POST')){$this->requireCsrf('/talk/settings');$this->talk->saveSettings(['auto_assign.enabled'=>Request::post('auto_assign_enabled')!==null?'1':'0','auto_assign.default_seconds'=>(string)max(5,(int)Request::post('auto_assign_default_seconds',30))],(int)$user->id);Response::to('/talk/settings?saved=1');}$this->page('Configurações','settings','Configurações gerais, canais e regras do Talk.',['settings'=>$this->talk->settings(),'channels'=>$this->talk->channels()]);}
private function filters():array{return ['q'=>(string)($_GET['q']??''),'status'=>(string)($_GET['status']??''),'priority'=>(string)($_GET['priority']??''),'queue_id'=>max(0,(int)($_GET['queue_id']??0)),'tag_id'=>max(0,(int)($_GET['tag_id']??0))];}private function requireCsrf(string $fallback):void{if(!Csrf::validate((string)Request::post('_token',''))){Response::to($fallback.'?error=csrf');}}private function page(string $title,string $currentPage,string $description,array $data=[]):void{echo $this->view->render('pages/talk-workspace',array_merge(['title'=>$title,'productName'=>'Talk','activeProduct'=>'talk','currentPage'=>$currentPage,'description'=>$description],$data));}
}
